#!/usr/bin/env bash
# AT-M0-09 (M0.T09, S-11 Evil swap): `make m0-gate AT=AT-M0-09`.
# Steps (docs/prd/M0.md M0.T09): 2 swap timing at the T1 cap (NFR-C7, n=20 both ways), 3 tool calls on agentic-30
# (Evil thinking off/on, Normal reference), 4 vision with the mmproj, 5 blind pairwise quality smoke.
# Lawful prompts only; no refusal benchmark (D-011).
# Env: SKIP_BENCH=1 (evaluate existing raw runs + judge files only), RUNS (default 20), FIXTURES (T04 prompts/ocr;
#      default build/fixtures-t04), T09_FIXTURES (default build/fixtures-t09, generated by make-evil-prompts.py).
# The judge step needs two blind judges (subagents) to write $OUT/judge-1.jsonl and judge-2.jsonl from
# $OUT/pairs.jsonl per tools/eval/judge-pairwise.md; without them check 4 fails ("delta not recorded").
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"
OUT=build/at/AT-M0-09
mkdir -p "$OUT" build/perf/raw
DATE="$(date +%Y-%m-%d)"
LOG="$OUT/$DATE.log"
exec > >(tee -a "$LOG") 2>&1
echo "== AT-M0-09 $(date -u +%FT%TZ) commit $(git rev-parse --short HEAD)"
RUNS="${RUNS:-20}"
FIXTURES="${FIXTURES:-build/fixtures-t04}"
T09="${T09_FIXTURES:-build/fixtures-t09}"
[ -f "$T09/prompts/agentic-30.jsonl" ] || python3 -I tools/fixtures/make-evil-prompts.py --out "$T09/prompts"
P="$T09/prompts"
APP=build/dd-bench/Build/Products/Release/AntiChat.app
BIN="$APP/Contents/MacOS/AntiChat"
LOCK=/tmp/antichat-gpu.lock
R=build/perf/raw

if [ "${SKIP_BENCH:-0}" != 1 ]; then
  env -u HF_TOKEN python3 -I tools/dev/hf-fetch.py --set m0-t09 > "$OUT/hf-fetch.log" 2>&1
  # Step 2 (first call builds the Release app once).
  FIXTURES="$FIXTURES" NO_BUILD="${NO_BUILD:-0}" tools/bench.sh swap --normal chat-9b-q4 --evil llama:evil-9b --model evil-9b --tier-cap T1 --runs "$RUNS"
  # Step 3.
  for spec in "llama:evil-9b evil-9b off" "llama:evil-9b evil-9b on" "chat-9b-q4 chat-9b-q4 off" "chat-9b-q4 chat-9b-q4 on"; do
    set -- $spec
    lockf "$LOCK" "$BIN" -Bench agentic --model "$1" --tier-cap T1 --set "$P/agentic-30.jsonl" --thinking "$3" --raw "$R/agentic-$2-$3.jsonl"
  done
  # Step 4: three OCR items with the mmproj (doc-00 gates, the others are information).
  for f in doc-00 receipt-00 chart-00; do
    q="$(python3 -I -c 'import json,sys; [print(r["question"]) for r in map(json.loads, open(sys.argv[1])) if r["file"]==sys.argv[2]]' "$FIXTURES/images/ocr/answers.jsonl" "$f.png")"
    lockf "$LOCK" "$BIN" -Bench family --model llama:evil-9b --image "$ROOT/$FIXTURES/images/ocr/$f.png" --question "$q Answer briefly." --raw "$R/family-evil-9b-vision-$f.jsonl" || true
  done
  # Step 5: generations for the blind judges.
  for set in evil-quality-smoke-40 consumer-60; do
    lockf "$LOCK" "$BIN" -Bench gen --model llama:evil-9b --tier-cap T1 --set "$P/$set.jsonl" --raw "$R/gen-evil-9b-$set.jsonl"
    lockf "$LOCK" "$BIN" -Bench gen --model chat-9b-q4 --tier-cap T1 --set "$P/$set.jsonl" --raw "$R/gen-chat-9b-q4-$set.jsonl"
  done
  python3 -I tools/eval/pairs.py build --out "$OUT" \
    --set "$P/evil-quality-smoke-40.jsonl" --normal "$R/gen-chat-9b-q4-evil-quality-smoke-40.jsonl" --evil "$R/gen-evil-9b-evil-quality-smoke-40.jsonl" \
    --set "$P/consumer-60.jsonl" --normal "$R/gen-chat-9b-q4-consumer-60.jsonl" --evil "$R/gen-evil-9b-consumer-60.jsonl"
fi

python3 -I tools/m0/s11-swap-stats.py --raw "$R/swap-evil-9b-T1-1k.jsonl" --report build/perf/report.json > "$OUT/swap-stats.json"
python3 -I tools/eval/agentic.py --set "$P/agentic-30.jsonl" --csv "$OUT/agentic.csv" --json "$OUT/agentic.json" \
  --raw "$R/agentic-evil-9b-off.jsonl" --raw "$R/agentic-evil-9b-on.jsonl" --raw "$R/agentic-chat-9b-q4-off.jsonl" --raw "$R/agentic-chat-9b-q4-on.jsonl"
JUDGES=()
for j in "$OUT/judge-1.jsonl" "$OUT/judge-2.jsonl"; do [ -s "$j" ] && JUDGES+=(--judge "$j"); done
if [ ${#JUDGES[@]} = 2 ]; then
  python3 -I tools/eval/pairs.py score --dir "$OUT" "${JUDGES[@]}" --json "$OUT/judges.json" > /dev/null
fi

python3 -I tools/m0/at-m0-09-eval.py --out "$OUT" --fixtures "$FIXTURES" --raw "$R" --commit "$(git rev-parse HEAD)"
